fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if string is non-empty
    if txt.is_empty() {
        return false;
    }
    
    // Get the last character
    let last_char = txt.chars().last().unwrap();
    
    // Check if last character is ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // Check the conditions for standalone letter
    if txt.len() == 1 {
        // Single character string - automatically standalone
        return true;
    } else {
        // For strings with more than one character,
        // check if character before last is a space
        let chars: Vec<char> = txt.chars().collect();
        let second_last_char = chars[chars.len() - 2];
        return second_last_char == ' ';
    }
}